--
-- Table structure for table `tour`
--

DROP TABLE IF EXISTS `tour`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tour` (
  `tour_id` int NOT NULL AUTO_INCREMENT,
  `location_id` int DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `author_id` int NOT NULL,
  `reviewer_id` int DEFAULT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_days` int NOT NULL DEFAULT '1',
  `category_name` varchar(250) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_per_adult` decimal(15,2) NOT NULL DEFAULT '0.00',
  `price_per_child` decimal(15,2) NOT NULL DEFAULT '0.00',
  `discount_price` decimal(15,2) DEFAULT NULL,
  `thumbnail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `images` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON Array storing images',
  `is_published` tinyint(1) DEFAULT '0',
  `start_dates` text COLLATE utf8mb4_unicode_ci,
  `is_hot` tinyint(1) DEFAULT '0',
  `is_featured` tinyint(1) DEFAULT '0',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `view_count` int DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'draft' COMMENT 'draft, pending, approved, rejected, published',
  `is_deleted` tinyint(1) DEFAULT '0',
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`tour_id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `fk_tour_location` (`location_id`),
  KEY `fk_tour_author` (`author_id`),
  KEY `fk_tour_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_tour_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tour_location` FOREIGN KEY (`location_id`) REFERENCES `locations` (`location_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tour_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tour`
--

LOCK TABLES `tour` WRITE;
/*!40000 ALTER TABLE `tour` DISABLE KEYS */;
INSERT INTO `tour` VALUES (1,1,'Khám Phá Di Sản Thủ Đô Hà Nội 1 Ngày',2,1,'Tour tham quan các địa điểm nổi tiếng lịch sử tại Hà Nội như Lăng Bác, Chùa Một Cột, Văn Miếu.','Khám phá Hà Nội qua các di tích lịch sử và thưởng thức ẩm thực đường phố đặc sắc trong vòng 1 ngày đầy trải nghiệm...',1,'culture',450000.00,250000.00,NULL,'/static/uploads/tour/vn/tour_1/20260621_095355_Hanoi2-1652338755-3632-1652338809.webp','[\"/static/uploads/tour/vn/tour_1/20260621_095402_image-14-1770196401104697172632-1770597593698-17705975942541511657137.webp\", \"/static/uploads/tour/vn/tour_1/20260621_095402_Hanoi_Skyline_-_NKS.jpg\", \"/static/uploads/tour/vn/tour_1/20260621_095446_optimize_gioi-thieu-ve-ha-noi-07.jpg\", \"/static/uploads/tour/vn/tour_1/20260621_095446_image-14-1770196401104697172632-1770597593698-17705975942541511657137.webp\"]',1,'[\"2026-06-21\", \"2026-06-22\", \"2026-06-24\"]',0,0,'kham-pha-di-san-thu-do-ha-noi-1-ngay',150,'published',0,'2026-06-21 03:11:07','2026-06-09 19:28:14','2026-06-21 09:47:37'),(2,2,'Du Thuyền Hạ Long Sang Trọng 2 Ngày 1 Đêm',2,1,'Trải nghiệm ngủ đêm trên vịnh Hạ Long với du thuyền 5 sao đẳng cấp quốc tế.','Hành trình 2 ngày 1 đêm đưa quý khách len lỏi qua các hang động kỳ vĩ, tham gia chèo thuyền kayak, lớp học nấu ăn trên tàu...',2,'beach',2450000.00,1600000.00,NULL,'/static/uploads/tour/vn/tour_2/20260621_095725_Ha_Long_2019_taken_by_DJI_FC220.jpg','[\"/static/uploads/tour/vn/tour_2/20260621_095737_c0c9124a-vinh-ha-long-1.jpg\", \"/static/uploads/tour/vn/tour_2/20260621_095738_Vinh-Ha-Long-1.jpg\", \"/static/uploads/tour/vn/tour_2/20260621_095738_vinhHaLongQuangNinh-1651912066-8789-1651932294.webp\"]',1,'[\"2026-06-23\", \"2026-06-27\", \"2026-06-30\"]',0,0,'du-thuyen-ha-long-sang-trong-2-ngay-1-dem',320,'published',0,'2026-06-21 03:11:10','2026-06-09 19:28:14','2026-06-21 09:47:37'),(3,3,'Đà Nẵng - Bà Nà Hills - Cầu Vàng Kỳ Thú 3 Ngày 2 Đêm',2,1,'Hành trình trọn vẹn khám phá Bà Nà Hills, check-in Cầu Vàng nổi tiếng thế giới.','Chiêm ngưỡng kiến trúc Làng Pháp lãng mạn, đi cáp treo đạt kỷ lục thế giới và đắm mình tại bãi biển Mỹ Khê xinh đẹp...',3,'resort',3800000.00,2400000.00,NULL,'/static/uploads/tour/vn/tour_3/20260621_095856_BNtop-1744279080-7298-1744280762.webp','[\"/static/uploads/tour/vn/tour_3/20260621_095909_ba-na-hills-1.jpg\", \"/static/uploads/tour/vn/tour_3/20260621_095909_toan-canh-khu-du-lich-sun-world-ba-na-hills.jpg\", \"/static/uploads/tour/vn/tour_3/20260621_095909_sun-world-ba-na-hills-ivivu45.jpg\", \"/static/uploads/tour/vn/tour_3/20260621_095909_h4-17038472022691152254010.webp\"]',1,'[\"2026-06-21\", \"2026-06-22\", \"2026-06-24\"]',0,0,'da-nang-ba-na-hills-cau-vang-3-ngay-2-dem',450,'published',0,'2026-06-21 03:11:13','2026-06-09 19:28:14','2026-06-21 09:47:37'),(4,4,'Thiên Đường Nắng Ấm Phú Quốc Tour 4 Ngày 3 Đêm',2,1,'Tour nghỉ dưỡng trọn gói tại Đảo Ngọc Phú Quốc với các hoạt động lặn ngắm san hô.','Khám phá phía Bắc đảo hoang sơ, check-in Grand World, tham gia tour 4 đảo bằng cano hiện đại và ngắm hoàng hôn Sunset Sanato...',4,'beach',5200000.00,3500000.00,NULL,'/static/uploads/tour/vn/tour_4/20260621_100209_dulichPhuQuoc-1649392573-9234-1649405369.webp','[\"/static/uploads/tour/vn/tour_4/20260621_100219_phu-quoc-2.webp\", \"/static/uploads/tour/vn/tour_4/20260621_100219_8ee94f3e-hon-thom-phu-quoc-1.jpg\", \"/static/uploads/tour/vn/tour_4/20260621_100220_phu-quoc-17506756503251936667562.jpg\"]',0,'[\"2026-07-08\", \"2026-07-11\", \"2026-07-16\"]',0,0,'thien-duong-nang-am-phu-quoc-4-ngay-3-dem',45,'published',0,'2026-06-21 03:11:16','2026-06-09 19:28:14','2026-06-21 09:47:37'),(5,5,'Hồ Chí Minh 5 ngày 4 đêm',2,1,'Du lịch Sài Gòn luôn mang đến những trải nghiệm khó quên với nhịp sống sôi động, văn hóa đa dạng và ẩm thực đặc sắc. Dù bạn đến đây lần đầu hay đã quen thuộc, mỗi chuyến đi đến các địa điểm du lịch thành phố Hồ Chí Minh đều mang lại những điều mới mẻ và đầy thú vị.','<p class=\"wp-block-paragraph\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; border: 0px solid rgb(226, 232, 240); margin: 0px 0px 10px; line-height: 28px; color: rgb(51, 51, 51); font-family: __Montserrat_069ab3, __Montserrat_Fallback_069ab3; font-size: medium;\"><span style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored