INSERT INTO `tour_comments` VALUES (1,2,3,NULL,'Chuyến đi du thuyền rất tuyệt vời, phòng ốc sạch sẽ, nhân viên phục vụ tận tình chu đáo!',1,'2026-06-09 19:28:14','2026-06-09 19:28:14'),(2,2,2,1,'Cảm ơn quý khách John Doe đã phản hồi tốt về dịch vụ của chúng tôi. Rất hân hạnh được phục vụ quý khách trong những chuyến đi tiếp theo!',1,'2026-06-09 19:28:14','2026-06-09 19:28:14'),(3,3,4,NULL,'Bà Nà Hills rất đẹp, tuy nhiên thời điểm đi hơi đông đúc nên phải xếp hàng cáp treo lâu.',1,'2026-06-09 19:28:14','2026-06-09 19:28:14');
